```

## Usage

```js
import { formatRelative } from "tiny-date";

formatRelative(new Date());
// "just now"

formatRelative(Date.now() - 5 * 60 * 1000);
// "5 minutes ago"

formatRelative(Date.now() + 2 * 60 * 60 * 1000);
// "in 2 hours"

formatRelative("2025-01-01T12:00:00Z", {
  now: "2025-01-02T12:00:00Z",
});
