```tsx
import { Button, Spinner, Tooltip } from "paw";

export function SaveButton({ saving }: { saving: boolean }) {
  return (
    <Tooltip content="Save your latest changes">
      <Button loading={saving}>
        {saving ? <Spinner label="Saving changes" /> : "Save"}
      </Button>
    </Tooltip>
  );
